  SELECT 1 FROM word WHERE category = 'CET4' AND word = 'zeal' AND translation = 'n.热心，热情，热忱'
);

INSERT INTO word (word, translation, level, category)
SELECT 'zealous', 'a.热心的，热情的', 2, 'CET4' FROM DUAL
WHERE NOT EXISTS (
  SELECT 1 FROM word WHERE category = 'CET4' AND word = 'zealous' AND translation = 'a.热心的，热情的'
);

